/** Move only badge faces at the viewport edges; bucket times, members and event guides stay unchanged. */
export function timelineRailMarkerPositions(buckets: EventMarkerBucket[], range: { start: number; end: number }, width: number): number[] {
  if (!buckets.length || !(width > 0) || !(range.end > range.start)) return [];
  const padding = Math.min(TIMELINE_RAIL_MARKER_SPACING / 2, width / 2,
    Math.max(TIMELINE_RAIL_PILL_WIDTH / 2, (width - (buckets.length - 1) * TIMELINE_RAIL_MARKER_SPACING) / 2));
  const gap = buckets.length > 1 ? Math.min(TIMELINE_RAIL_MARKER_SPACING, (width - padding * 2) / (buckets.length - 1)) : 0;
  const positions: number[] = [];
  for (const bucket of buckets) {
    const anchor = (bucket.time - range.start) / (range.end - range.start) * width;
    positions.push(Math.max(padding, Math.min(width - padding, anchor), (positions[positions.length - 1] ?? padding - gap) + gap));
  }
  for (let i = positions.length - 1; i >= 0; i--) {
    positions[i] = Math.min(positions[i], i === positions.length - 1 ? width - padding : positions[i + 1] - gap);
  }
  return positions;
}
