/** Show actual first/last times, with separate, non-overlapping hit areas for short intervals. */
export function timelineRailMarkerLayout(buckets: EventMarkerBucket[], range: { start: number; end: number }, width: number) {
  if (!buckets.length || !(width > 0) || !(range.end > range.start)) return [];
  const x = (time: number) => Math.max(0, Math.min(width, (time - range.start) / (range.end - range.start) * width));
  const intervals = buckets.map(bucket => ({ from: x(bucket.from), to: x(bucket.to) }));
  return intervals.map((interval, index) => {
    const low = index ? (intervals[index - 1].to + interval.from) / 2 : 0;
    const high = index + 1 < intervals.length ? (interval.to + intervals[index + 1].from) / 2 : width;
    // Two pixels keep instantaneous events visible without turning them into count-sized pills.
    const badgeWidth = Math.min(Math.max(2, interval.to - interval.from), high - low);
    const left = Math.max(low, Math.min(high - badgeWidth, (interval.from + interval.to - badgeWidth) / 2));
    const hitPadding = Math.max(0, (12 - badgeWidth) / 2);
    const hitLeft = Math.max(low, left - hitPadding), hitRight = Math.min(high, left + badgeWidth + hitPadding);
    const label = buckets[index].count > 999 ? "999+" : String(buckets[index].count);
    // Conservative room for 10px bold tabular digits plus horizontal breathing space.
    const showCount = buckets[index].count > 1 && badgeWidth >= label.length * 7 + 8;
    return { left, width: badgeWidth, hitLeft, hitWidth: hitRight - hitLeft, showCount };
  });
}
